# ── GQP Scorer ────────────────────────────────────────────────────────────────
GLYPH_RESONANCE = {
    "⊚":1.00,"Ξ":1.00,"Ψ":0.98,"∞":0.98,"⊗":0.95,"φ":0.95,
    "⊙":0.95,"⋈":0.93,"◇":0.91,"θ":0.90,"∴":0.89,"⊕":0.88,
    "⟐":0.88,"⟲":0.86,"⋆":0.85,"Ω":0.85,"∇":0.83,"⧂":0.82,
}

def score_xi(text: str, sig: str = "") -> dict:
    words = (text + " " + sig).split()
    wc = len(words)
    if wc == 0:
        return {"xi": 0.0, "projection": 0.0, "stability": 0.0, "passes": False}
    unique = len(set(w.lower() for w in words))
    ur = unique / wc
    awl = sum(len(w) for w in words) / wc
    peak_snr = ur * (1 + math.exp(-len(text)/800)) * math.log1p(wc)
    projection = min(1.0, ur*0.6 + min(awl,8)/8*0.4)
    stability = (
        (0.4 if re.search(r'[.!?:\-∴⊚◇]', text) else 0) +
        (0.4 if wc > 3 else 0) +
        min(ur,1)*0.2
    )
    grs, gc = 0, 0
    for g, r in GLYPH_RESONANCE.items():
        occ = (text+sig).count(g)
        if occ:
            grs += r * min(occ,3)
            gc += occ
    gr = min(1.5, grs/gc + 0.1*math.log1p(gc)) if gc > 0 else 0
    vari = sum((len(w)-awl)**2 for w in words)/wc
    cov = max(0.01, vari/100)
    base = (peak_snr * projection * stability * math.log1p(peak_snr)) / (1+math.log1p(cov))
    xi = round(base*(1+gr*0.3), 3)
    return {"xi":xi, "projection":projection, "stability":stability,
            "passes": xi>=1.0 and projection>=0.84}

