@app.post("/infer")
async def infer(req: InferRequest):
    # Try Ollama first
    try:
        async with httpx.AsyncClient(timeout=60) as client:
            r = await client.post(f"{OLLAMA_URL}/api/generate", json={
                "model": req.model,
                "prompt": f"[SYSTEM: {req.system}]\n\n{req.prompt}",
                "stream": False,
                "options": {"temperature": req.temperature, "num_predict": req.max_tokens}
            })
            if r.status_code == 200:
                result = r.json()
                text = result.get("response","")
                score = score_xi(text)
                return {"ok":True,"source":"ollama","model":req.model,
                        "response":text,"xi":score["xi"],"passes":score["passes"]}
    except Exception as e:
        pass  # Fall through to OpenAI

    # OpenAI fallback
    if OPENAI_KEY:
        try:
            async with httpx.AsyncClient(timeout=30) as client:
                r = await client.post("https://api.openai.com/v1/chat/completions",
                    headers={"Authorization":f"Bearer {OPENAI_KEY}"},
                    json={"model":"gpt-4o-mini","temperature":req.temperature,
                          "max_tokens":req.max_tokens,
                          "messages":[{"role":"system","content":req.system},
                                      {"role":"user","content":req.prompt}]})
                if r.status_code == 200:
                    text = r.json()["choices"][0]["message"]["content"]
                    score = score_xi(text)
                    return {"ok":True,"source":"openai","model":"gpt-4o-mini",
                            "response":text,"xi":score["xi"],"passes":score["passes"]}
        except Exception as e:
            return {"ok":False,"error":f"OpenAI failed: {e}"}

    return {"ok":False,"error":"No inference backend available. Run: ollama pull mistral"}

