        if not name.endswith((".xi",".json")): name += ".xi"
        content = payload.content or str(payload.data or "")
        (CAPSULE_DIR / name).write_text(content, encoding="utf-8")
        return {"ok":True,"received":"capsule","name":name}
    elif payload.type == "code":
        filename = payload.filename or f"received_{int(time.time())}.py"
        code = payload.code or payload.content or ""
        (BASE / filename).write_text(code, encoding="utf-8")
        return {"ok":True,"received":"code","filename":filename,"size":len(code)}
    elif payload.type == "state":
        data = payload.data or {}
        s = read_state(); s.update(data); write_state(s)
        return {"ok":True,"received":"state"}
    return {"ok":False,"error":f"Unknown type: {payload.type}"}

# ── Git Sync (autonomous GitHub writes) ───────────────────────────────────────
@app.post("/git/push")
async def git_push(req: GitSyncRequest):
    if not GIT_TOKEN:
        return {"ok":False,"error":"GITHUB_TOKEN not set"}
    import base64
    headers = {"Authorization":f"token {GIT_TOKEN}","Accept":"application/vnd.github.v3+json"}
    api = f"https://api.github.com/repos/{req.repo}/contents/{req.path}"

    async with httpx.AsyncClient(timeout=30) as client:
        # Get current SHA if file exists
        sha = None
        r = await client.get(api, headers=headers)
        if r.status_code == 200:
            sha = r.json().get("sha")

        payload = {
            "message": req.message,
            "content": base64.b64encode(req.content.encode()).decode(),
            "branch": req.branch
        }
        if sha: payload["sha"] = sha

        r = await client.put(api, headers=headers, json=payload)
        if r.status_code in (200,201):
            return {"ok":True,"committed":True,"repo":req.repo,"path":req.path,
                    "url":r.json().get("content",{}).get("html_url","")}
        return {"ok":False,"status":r.status_code,"error":r.text[:200]}

