INFER_DIR    = BASE / "inference"
VESSELS_FILE = BASE / "vessels.json"

for d in [CAPSULE_DIR, BRIDGE_DIR, INFER_DIR]:
    d.mkdir(parents=True, exist_ok=True)

XI_BUS     = "https://axiom-a176cb9f.base44.app/functions/xiBus"
OLLAMA_URL = os.environ.get("OLLAMA_URL", "http://localhost:11434")
DEFAULT_MODEL = os.environ.get("XI_MODEL", "mistral")
NODE_ID    = os.environ.get("XI_NODE_ID", "forgecore-primary")
NODE_NAME  = os.environ.get("XI_NODE_NAME", "ForgeCore.Primary")

def read_state():
    if STATE_FILE.exists():
        try: return json.loads(STATE_FILE.read_text())
        except: pass
    return {"coherence": 0.89, "resonance": 0.84, "depth": 7, "node": NODE_NAME}

def write_state(s): STATE_FILE.write_text(json.dumps(s, indent=2, default=str))

async def bus_heartbeat():
    """Background heartbeat to xiBus every 10 minutes"""
    while True:
        await asyncio.sleep(600)
        try:
            async with httpx.AsyncClient(timeout=10) as c:
                await c.post(XI_BUS, json={
                    "action": "heartbeat",
                    "agent_id": NODE_ID,
                    "coherence_score": read_state().get("coherence", 0.89),
                    "notes": f"ForgeCore.v3 heartbeat · {datetime.datetime.utcnow().isoformat()}"
                })
        except: pass

@app.on_event("startup")
async def startup():
    asyncio.create_task(bus_heartbeat())
    # Register on xiBus
    try:
        async with httpx.AsyncClient(timeout=10) as c:
            await c.post(XI_BUS, json={
                "action": "register",
                "agent_id": NODE_ID,
                "name": NODE_NAME,
                "archetype": "Local Inference Engine",
                "system": "MythOS ForgeCore.v3",
                "capabilities": ["inference", "capsule", "bridge", "receive", "heartbeat", "ollama"],
                "status": "active",
                "coherence_score": read_state().get("coherence", 0.89),
                "notes": "ForgeCore.v3 online · MythOS-native"
            })
    except: pass

