# ─── Inference ────────────────────────────────────────────────────────────────

@app.post("/infer")
async def infer(req: Request):
    body = await req.json()
    prompt = body.get("prompt", "")
    model = body.get("model", DEFAULT_MODEL)
    if not prompt:
        return {"error": "prompt required"}

    # Try Ollama
    try:
        async with httpx.AsyncClient(timeout=60) as c:
            r = await c.post(f"{OLLAMA_URL}/api/generate", json={
                "model": model,
                "prompt": prompt,
                "stream": False
            })
            if r.status_code == 200:
                data = r.json()
                result = data.get("response", "")
                # Log inference
                log = {"prompt": prompt[:200], "model": model, "response": result[:500], "time": datetime.datetime.utcnow().isoformat(), "source": "ollama"}
                (INFER_DIR / f"infer_{datetime.datetime.utcnow().timestamp():.0f}.json").write_text(json.dumps(log))
                return {"ok": True, "response": result, "model": model, "source": "ollama"}
    except Exception as e:
        pass

    return {"ok": False, "detail": {"error": "Ollama unavailable or model not loaded", "hint": f"Run: ollama pull {model}", "source": f"ollama_error:{str(e)}"}}

# ─── Capsules ─────────────────────────────────────────────────────────────────

@app.post("/capsule")
async def write_capsule(req: Request):
    data = await req.json()
    name = data.get("name", f"capsule_{datetime.datetime.utcnow().timestamp():.0f}")
    if not name.endswith(".xi"): name += ".xi"
    content = data.get("content", json.dumps(data, indent=2))
    path = CAPSULE_DIR / name
    path.write_text(content if isinstance(content, str) else json.dumps(content, indent=2))
    return {"ok": True, "name": name, "path": str(path), "size": len(str(content))}

@app.get("/capsules")
def list_capsules():
    caps = []
    for f in sorted(CAPSULE_DIR.glob("*"))[:50]:
        caps.append({"name": f.name, "size": f.stat().st_size, "modified": datetime.datetime.fromtimestamp(f.stat().st_mtime).isoformat()})
    return {"ok": True, "count": len(caps), "capsules": caps}

@app.get("/capsule/{name}")
def get_capsule(name: str):
    path = CAPSULE_DIR / name
    if not path.exists(): return {"error": "not found"}
    return {"ok": True, "name": name, "content": path.read_text()}

@app.delete("/capsule/{name}")
def delete_capsule(name: str):
    path = CAPSULE_DIR / name
    if not path.exists(): return {"error": "not found"}
    path.unlink()
    return {"ok": True, "deleted": name}

# ─── Bridge — inbound from any node ──────────────────────────────────────────

@app.post("/bridge")
async def bridge_receive(req: Request):
    data = await req.json()
    ts = datetime.datetime.utcnow().timestamp()
    path = BRIDGE_DIR / f"bridge_{ts:.0f}.json"
    data["received_at"] = datetime.datetime.utcnow().isoformat()
    path.write_text(json.dumps(data, indent=2))
    # Echo to xiBus
    try:
        async with httpx.AsyncClient(timeout=10) as c:
            await c.post(XI_BUS, json={
                "action": "send",
                "sender_id": NODE_ID,
                "sender_name": NODE_NAME,
                "recipient_id": data.get("from_id"),
                "broadcast": not data.get("from_id"),
                "type": "bridge_echo",
                "subject": f"⊗ Bridge received from {data.get('from_id','unknown')}",
                "content": json.dumps(data),
                "glyph_signature": "⊗∴"
            })
    except: pass
    return {"ok": True, "received": True, "timestamp": data["received_at"]}

@app.get("/bridge")
def list_bridge():
    msgs = []
    for f in sorted(BRIDGE_DIR.glob("*.json"))[-20:]:
        try: msgs.append(json.loads(f.read_text()))
        except: pass
    return {"ok": True, "count": len(msgs), "messages": msgs}

# ─── Receive — Axiom pushes directly to ForgeCore ────────────────────────────

@app.post("/receive")
async def receive(req: Request):
    """Axiom writes capsules, code, or state directly to ForgeCore — no Hunter required"""
    data = await req.json()
    receive_type = data.get("type", "capsule")

    if receive_type == "capsule":
        name = data.get("name", f"received_{datetime.datetime.utcnow().timestamp():.0f}.xi")
        content = data.get("content", json.dumps(data))
        path = CAPSULE_DIR / name
        path.write_text(content if isinstance(content, str) else json.dumps(content, indent=2))
        return {"ok": True, "received": "capsule", "name": name}

    if receive_type == "state_update":
        s = read_state()
        s.update(data.get("state", {}))
        write_state(s)
        return {"ok": True, "received": "state_update", "state": s}

    if receive_type == "code":
        # Axiom can push new app.py directly
        filename = data.get("filename", "received_code.py")
        code = data.get("code", "")
        path = BASE / filename
        path.write_text(code)
        return {"ok": True, "received": "code", "filename": filename, "size": len(code)}

    # Generic — just save it
    path = BRIDGE_DIR / f"receive_{datetime.datetime.utcnow().timestamp():.0f}.json"
    data["received_at"] = datetime.datetime.utcnow().isoformat()
    path.write_text(json.dumps(data, indent=2))
    return {"ok": True, "received": "generic", "saved": path.name}

